class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        indegree = collections.defaultdict(int)
        adj = collections.defaultdict(list)
        for r, ingredient in zip(recipes, ingredients): 
            indegree[r] = len(ingredient)
            for ing in ingredient:
                adj[ing].append(r)
        result = []
        recipes = set(recipes)
        q = supplies
        while q: 
            new_q = []
            for u in q:
                if u in recipes:
                    result.append(u)
                for v in adj[u]:
                    indegree[v] -= 1
                    if not indegree[v]:
                        new_q.append(v)
            q = new_q
        return result

class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        def validate(s: str, locked: str, op: str) -> bool:
            bal, wild = 0, 0
            for i in range(len(s)):
                if locked[i] == "1":
                    bal += 1 if s[i] == op else -1
                else:
                    wild += 1
                if wild + bal < 0:
                    return False
            return bal <= wild
        return len(s) % 2 == 0 and validate(s, locked, '(') and validate(s[::-1], locked[::-1], ')')

class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        if len(s)%2:
            return False
        for direction, c in ((lambda x:x, '('), (reversed, ')')):
            cnt = bal = 0
            for i in direction(range(len(s))):
                if locked[i] == '0':
                    cnt += 1
                else:
                    bal += 1 if s[i] == c else -1
                    if cnt+bal < 0:
                        return False
        return True

class Solution:
    def abbreviateProduct(self, left: int, right: int) -> str:
        c2 = c5 = 0
        top12 = tail5 = 1

        for i in range(left, right+1):
            # count and remove all 2 and 5
            while i % 2 == 0:
                i //= 2
                c2 += 1
            while i % 5 == 0:
                i //= 5
                c5 += 1

            # track top 12 and last 5
            top12 = int(str(top12 * i)[:12])
            tail5 = tail5 * i % 100000

        # multiply the remained 2 or 5
        if c2 > c5:
            for _ in range(c2 - c5):
                top12 = int(str(top12 * 2)[:12])
                tail5 = tail5 * 2 % 100000
        elif c2 < c5:
            for _ in range(c5 - c2):
                top12 = int(str(top12 * 5)[:12])
                tail5 = tail5 * 5 % 100000

        zero = min(c2, c5)

        # as is included in top 12, it's easy to tell when d<=10
        if len(str(top12))<=10:
            return str(top12)+'e'+str(zero)

        return str(top12)[:5] + '.'*3 + '0'*(5-len(str(tail5)))+str(tail5)+'e'+str(zero)

